// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {B20Constants} from "./B20Constants.sol";
import {IB20} from "./IB20.sol";
import {IB20Asset} from "./IB20Asset.sol";
import {IB20Factory} from "./IB20Factory.sol";

/// @title  B20FactoryLib
/// @author Coinbase
/// @notice Pure encoder helpers for the `params` blob and `initCalls` array consumed by
///         `IB20Factory.createB20`. No precompile dispatch, no storage reads, no auth checks.
library B20FactoryLib {
    /// @notice Encoding version carried as the leading byte of a `B20StablecoinCreateParams` blob.
    uint8 internal constant B20_STABLECOIN_CREATE_PARAMS_VERSION = 1;

    /// @notice Encoding version carried as the leading byte of a `B20AssetCreateParams` blob.
    uint8 internal constant B20_ASSET_CREATE_PARAMS_VERSION = 1;

    /// @notice Encoding version carried as the leading byte of a `B20StablecoinEventParams` blob.
    uint8 internal constant B20_STABLECOIN_EVENT_PARAMS_VERSION = 1;

    /// @notice Two parallel arrays passed to a `build*` helper had different lengths.
    ///
    /// @param  leftLen  Length of the first array argument.
    /// @param  rightLen Length of the second array argument.
    error LengthMismatch(uint256 leftLen, uint256 rightLen);

    /*//////////////////////////////////////////////////////////////
                          ROLE-HOLDER BUNDLES
    //////////////////////////////////////////////////////////////*/

    /// @notice Bootstrap role-grant bundle for `B20Variant.STABLECOIN`.
    ///         `address(0)` fields are skipped at bootstrap.
    ///
    /// @dev    `DEFAULT_ADMIN_ROLE` is assigned via `B20StablecoinCreateParams.initialAdmin`, not this struct.
    struct B20RoleHolders {
        /// @dev Account granted `MINT_ROLE`.
        address minter;
        /// @dev Account granted `BURN_ROLE`.
        address burner;
        /// @dev Account granted `BURN_BLOCKED_ROLE`.
        address burnBlocker;
        /// @dev Account granted `PAUSE_ROLE`.
        address pauser;
        /// @dev Account granted `UNPAUSE_ROLE`.
        address unpauser;
        /// @dev Account granted `METADATA_ROLE`.
        address metadataAdmin;
    }

    /// @notice Bootstrap role-grant bundle for `B20Variant.ASSET`. Superset of `B20RoleHolders`
    ///         with an `OPERATOR_ROLE` slot.
    ///
    /// @dev    `DEFAULT_ADMIN_ROLE` is assigned via `B20AssetCreateParams.initialAdmin`, not this struct.
    struct B20AssetRoleHolders {
        /// @dev Account granted `MINT_ROLE`.
        address minter;
        /// @dev Account granted `BURN_ROLE`.
        address burner;
        /// @dev Account granted `BURN_BLOCKED_ROLE`.
        address burnBlocker;
        /// @dev Account granted `PAUSE_ROLE`.
        address pauser;
        /// @dev Account granted `UNPAUSE_ROLE`.
        address unpauser;
        /// @dev Account granted `METADATA_ROLE`.
        address metadataAdmin;
        /// @dev Account granted `OPERATOR_ROLE`.
        address operator;
    }

    /*//////////////////////////////////////////////////////////////
                          CREATE-PARAMS ENCODERS
    //////////////////////////////////////////////////////////////*/

    /// @notice Encodes a `B20StablecoinCreateParams` blob tagged with `B20_STABLECOIN_CREATE_PARAMS_VERSION`.
    ///
    /// @param name         ERC-20 token name.
    /// @param symbol       ERC-20 token symbol.
    /// @param initialAdmin Initial holder of `DEFAULT_ADMIN_ROLE`, or `address(0)` to deploy admin-less.
    /// @param currency     Self-declared currency code (uppercase ASCII).
    function encodeStablecoinCreateParams(
        string memory name,
        string memory symbol,
        address initialAdmin,
        string memory currency
    ) internal pure returns (bytes memory) {
        return abi.encode(
            IB20Factory.B20StablecoinCreateParams({
                version: B20_STABLECOIN_CREATE_PARAMS_VERSION,
                name: name,
                symbol: symbol,
                initialAdmin: initialAdmin,
                currency: currency
            })
        );
    }

    /// @notice Encodes a `B20AssetCreateParams` blob tagged with `B20_ASSET_CREATE_PARAMS_VERSION`.
    ///
    /// @param name         ERC-20 token name.
    /// @param symbol       ERC-20 token symbol.
    /// @param initialAdmin Initial holder of `DEFAULT_ADMIN_ROLE`, or `address(0)` to deploy admin-less.
    /// @param decimals     ERC-20 `decimals` value. Must be in `[B20Constants.MIN_ASSET_DECIMALS, B20Constants.MAX_ASSET_DECIMALS]`;
    ///                     out-of-range values cause the factory to revert with `InvalidDecimals`.
    function encodeAssetCreateParams(string memory name, string memory symbol, address initialAdmin, uint8 decimals)
        internal
        pure
        returns (bytes memory)
    {
        return abi.encode(
            IB20Factory.B20AssetCreateParams({
                version: B20_ASSET_CREATE_PARAMS_VERSION,
                name: name,
                symbol: symbol,
                initialAdmin: initialAdmin,
                decimals: decimals
            })
        );
    }

    /// @notice Encodes a `B20StablecoinEventParams` as the `variantEventParams` blob the factory
    ///         emits in the `B20Created` event for `B20Variant.STABLECOIN`.
    ///
    /// @param currency ISO 4217 fiat code this stablecoin tracks.
    function encodeStablecoinEventParams(string memory currency) internal pure returns (bytes memory) {
        return abi.encode(
            IB20Factory.B20StablecoinEventParams({version: B20_STABLECOIN_EVENT_PARAMS_VERSION, currency: currency})
        );
    }

    /*//////////////////////////////////////////////////////////////
                        INIT-CALL SETTER ENCODERS
    //////////////////////////////////////////////////////////////*/

    /// @notice Encodes a bootstrap initCall to `IB20.updateSupplyCap`.
    /// @param newSupplyCap New supply cap (`type(uint128).max` for no cap).
    function encodeUpdateSupplyCap(uint256 newSupplyCap) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.updateSupplyCap, (newSupplyCap));
    }

    /// @notice Encodes a bootstrap initCall to `IB20.updateContractURI`.
    /// @param newURI New contract URI (ERC-7572).
    function encodeUpdateContractURI(string memory newURI) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.updateContractURI, (newURI));
    }

    /// @notice Encodes a bootstrap initCall to `IB20.updateName`.
    /// @param newName New ERC-20 token name.
    function encodeUpdateName(string memory newName) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.updateName, (newName));
    }

    /// @notice Encodes a bootstrap initCall to `IB20.updatePolicy`.
    ///
    /// @param policyScope The policy-slot scope.
    /// @param newPolicyId The new policy registry ID.
    function encodeUpdatePolicy(bytes32 policyScope, uint64 newPolicyId) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.updatePolicy, (policyScope, newPolicyId));
    }

    /// @notice Encodes a bootstrap initCall to `IB20.grantRole`.
    ///
    /// @param role    Role to grant.
    /// @param account Account to grant the role to.
    function encodeGrantRole(bytes32 role, address account) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.grantRole, (role, account));
    }

    /// @notice Encodes a bootstrap initCall to `IB20.revokeRole`.
    ///
    /// @param role    Role to revoke.
    /// @param account Account to revoke the role from.
    function encodeRevokeRole(bytes32 role, address account) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.revokeRole, (role, account));
    }

    /// @notice Encodes a bootstrap initCall to `IB20.setRoleAdmin`.
    ///
    /// @param role         Role whose admin is being changed.
    /// @param newAdminRole New admin role for `role`.
    function encodeSetRoleAdmin(bytes32 role, bytes32 newAdminRole) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20.setRoleAdmin, (role, newAdminRole));
    }

    /// @notice Encodes a bootstrap initCall to `IB20Asset.batchMint`.
    ///
    /// @param recipients Accounts receiving the minted tokens.
    /// @param amounts    Per-recipient amounts, parallel to `recipients`.
    function encodeBatchMint(address[] memory recipients, uint256[] memory amounts)
        internal
        pure
        returns (bytes memory)
    {
        return abi.encodeCall(IB20Asset.batchMint, (recipients, amounts));
    }

    /// @notice Encodes a bootstrap initCall to `IB20Asset.updateExtraMetadata`.
    ///
    /// @param key   Metadata entry key (e.g. `"category"`).
    /// @param value New value, or empty string to remove.
    function encodeUpdateExtraMetadata(string memory key, string memory value) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20Asset.updateExtraMetadata, (key, value));
    }

    /// @notice Encodes an initCall / announce inner call to the canonical scheduled
    ///         `IB20Asset.updateUIMultiplier`.
    /// @param newMultiplier New multiplier, scaled to `WAD_PRECISION`.
    /// @param effectiveAt   Timestamp at which `newMultiplier` becomes effective; must be in the future.
    function encodeUpdateUIMultiplier(uint256 newMultiplier, uint256 effectiveAt) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20Asset.updateUIMultiplier, (newMultiplier, effectiveAt));
    }

    /// @notice Encodes a bootstrap initCall to the deprecated instant `IB20Asset.updateMultiplier`.
    /// @dev Retained for backward compatibility; prefer the scheduled `encodeUpdateUIMultiplier`.
    /// @param newMultiplier New multiplier, scaled to `WAD_PRECISION`.
    function encodeUpdateMultiplier(uint256 newMultiplier) internal pure returns (bytes memory) {
        return abi.encodeCall(IB20Asset.updateMultiplier, (newMultiplier));
    }

    /// @notice Encodes an announce inner call to `IB20Asset.cancelUIMultiplierUpdate`.
    function encodeCancelUIMultiplierUpdate() internal pure returns (bytes memory) {
        return abi.encodeCall(IB20Asset.cancelUIMultiplierUpdate, ());
    }

    /*//////////////////////////////////////////////////////////////
                       INIT-CALL ARRAY BUILDERS
    //////////////////////////////////////////////////////////////*/

    /// @notice Builds the `grantRole` initCalls implied by a `B20RoleHolders` bundle, in struct-field
    ///         order. `address(0)` fields are skipped; the result is sized exactly to the kept entries.
    ///
    /// @param holders Role-holder bundle.
    /// @return initCalls ABI-encoded `grantRole` initCalls.
    function buildRoleGrants(B20RoleHolders memory holders) internal pure returns (bytes[] memory initCalls) {
        bytes32[] memory roles = new bytes32[](6);
        roles[0] = B20Constants.MINT_ROLE;
        roles[1] = B20Constants.BURN_ROLE;
        roles[2] = B20Constants.BURN_BLOCKED_ROLE;
        roles[3] = B20Constants.PAUSE_ROLE;
        roles[4] = B20Constants.UNPAUSE_ROLE;
        roles[5] = B20Constants.METADATA_ROLE;

        address[] memory accounts = new address[](6);
        accounts[0] = holders.minter;
        accounts[1] = holders.burner;
        accounts[2] = holders.burnBlocker;
        accounts[3] = holders.pauser;
        accounts[4] = holders.unpauser;
        accounts[5] = holders.metadataAdmin;

        return buildRoleGrants(roles, accounts);
    }

    /// @notice Same as `buildRoleGrants(B20RoleHolders)`, but for the asset role set.
    ///
    /// @param holders Asset role-holder bundle.
    /// @return initCalls ABI-encoded `grantRole` initCalls.
    function buildRoleGrants(B20AssetRoleHolders memory holders) internal pure returns (bytes[] memory initCalls) {
        bytes32[] memory roles = new bytes32[](7);
        roles[0] = B20Constants.MINT_ROLE;
        roles[1] = B20Constants.BURN_ROLE;
        roles[2] = B20Constants.BURN_BLOCKED_ROLE;
        roles[3] = B20Constants.PAUSE_ROLE;
        roles[4] = B20Constants.UNPAUSE_ROLE;
        roles[5] = B20Constants.METADATA_ROLE;
        roles[6] = B20Constants.OPERATOR_ROLE;

        address[] memory accounts = new address[](7);
        accounts[0] = holders.minter;
        accounts[1] = holders.burner;
        accounts[2] = holders.burnBlocker;
        accounts[3] = holders.pauser;
        accounts[4] = holders.unpauser;
        accounts[5] = holders.metadataAdmin;
        accounts[6] = holders.operator;

        return buildRoleGrants(roles, accounts);
    }

    /// @notice Builds the `grantRole` initCalls implied by parallel `roles` / `accounts` arrays.
    ///         Entries where `accounts[k] == address(0)` are skipped; the result preserves input order
    ///         and is sized exactly to the kept entries.
    ///
    /// @dev Reverts with `LengthMismatch` when `roles.length != accounts.length`.
    ///
    /// @param roles    Roles to grant, parallel to `accounts`.
    /// @param accounts Role holders, parallel to `roles`.
    /// @return initCalls ABI-encoded `grantRole` initCalls.
    function buildRoleGrants(bytes32[] memory roles, address[] memory accounts)
        internal
        pure
        returns (bytes[] memory initCalls)
    {
        if (roles.length != accounts.length) revert LengthMismatch(roles.length, accounts.length);

        uint256 grantCount;
        for (uint256 k = 0; k < accounts.length; k++) {
            if (accounts[k] != address(0)) grantCount++;
        }

        initCalls = new bytes[](grantCount);
        uint256 i;
        for (uint256 k = 0; k < accounts.length; k++) {
            if (accounts[k] != address(0)) {
                initCalls[i++] = encodeGrantRole(roles[k], accounts[k]);
            }
        }
    }

    /// @notice Builds the `updateExtraMetadata` initCalls implied by parallel
    ///         `keys` / `values` arrays. All entries are emitted in input order.
    ///
    /// @dev Reverts with `LengthMismatch` when `keys.length != values.length`.
    ///
    /// @param keys   Metadata entry keys (e.g. `"category"`).
    /// @param values Values parallel to `keys`.
    /// @return initCalls ABI-encoded `updateExtraMetadata` initCalls.
    function buildExtraMetadataUpdates(string[] memory keys, string[] memory values)
        internal
        pure
        returns (bytes[] memory initCalls)
    {
        if (keys.length != values.length) {
            revert LengthMismatch(keys.length, values.length);
        }

        initCalls = new bytes[](keys.length);
        for (uint256 k = 0; k < keys.length; k++) {
            initCalls[k] = encodeUpdateExtraMetadata(keys[k], values[k]);
        }
    }

    /// @notice Concatenates `head` and `tail` into a single init-call array, preserving order.
    ///
    /// @param head Init calls placed first.
    /// @param tail Init calls placed after `head`. May be empty.
    /// @return initCalls Concatenated array, sized `head.length + tail.length`.
    function concat(bytes[] memory head, bytes[] memory tail) internal pure returns (bytes[] memory initCalls) {
        initCalls = new bytes[](head.length + tail.length);
        uint256 i;
        for (uint256 k = 0; k < head.length; k++) {
            initCalls[i++] = head[k];
        }
        for (uint256 k = 0; k < tail.length; k++) {
            initCalls[i++] = tail[k];
        }
    }
}

B20/B20Constants.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title B20Constants
/// @notice Canonical B-20 role and policy-type constants, exposed for compile-time use.
library B20Constants {
    bytes32 internal constant DEFAULT_ADMIN_ROLE = bytes32(0);
    bytes32 internal constant MINT_ROLE = keccak256("MINT_ROLE");
    bytes32 internal constant BURN_ROLE = keccak256("BURN_ROLE");
    bytes32 internal constant BURN_BLOCKED_ROLE = keccak256("BURN_BLOCKED_ROLE");
    bytes32 internal constant SEIZE_ROLE = keccak256("SEIZE_ROLE");
    bytes32 internal constant PAUSE_ROLE = keccak256("PAUSE_ROLE");
    bytes32 internal constant UNPAUSE_ROLE = keccak256("UNPAUSE_ROLE");
    bytes32 internal constant METADATA_ROLE = keccak256("METADATA_ROLE");
    bytes32 internal constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    bytes32 internal constant TRANSFER_SENDER_POLICY = keccak256("TRANSFER_SENDER_POLICY");
    bytes32 internal constant TRANSFER_RECEIVER_POLICY = keccak256("TRANSFER_RECEIVER_POLICY");
    bytes32 internal constant TRANSFER_EXECUTOR_POLICY = keccak256("TRANSFER_EXECUTOR_POLICY");
    bytes32 internal constant MINT_RECEIVER_POLICY = keccak256("MINT_RECEIVER_POLICY");
    bytes32 internal constant SEIZE_HOLDER_POLICY = keccak256("SEIZE_HOLDER_POLICY");
    bytes32 internal constant SEIZE_RECEIVER_POLICY = keccak256("SEIZE_RECEIVER_POLICY");

    /// @notice Bitmask with all `PausableFeature` bits set (TRANSFER | MINT | BURN | SEIZE); 15 = 0b1111.
    uint8 internal constant ALL_FEATURES_PAUSED = 15;

    /// @notice Inclusive lower bound for `B20AssetCreateParams.decimals`. `6` is the
    ///         floor most stablecoin-grade integrations expect; values below it lose
    ///         meaningful unit precision for asset workflows.
    uint8 internal constant MIN_ASSET_DECIMALS = 6;

    /// @notice Inclusive upper bound for `B20AssetCreateParams.decimals`. `18` is the
    ///         ERC-20 community ceiling — every common wallet and indexer renders up to
    ///         18 decimals correctly; going higher risks integration breakage.
    uint8 internal constant MAX_ASSET_DECIMALS = 18;

    /// @notice Inclusive upper bound for the supply cap, and therefore for `totalSupply`.
    ///         `type(uint128).max` also serves as the unbounded ("no cap") sentinel: a cap
    ///         set to this value imposes no practical limit while keeping supply within `uint128`.
    uint256 internal constant MAX_SUPPLY_CAP = type(uint128).max;
}

B20/IB20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.20 <0.9.0;

/// @title IB20
///
/// @notice The base Solidity surface every Base-native token (B-20) implements. Variants
///         (Asset, Stablecoin) extend this interface; nothing on this surface is
///         variant-specific.
interface IB20 {
    /*//////////////////////////////////////////////////////////////
                                  TYPES
    //////////////////////////////////////////////////////////////*/

    /// @notice Pausable operation classes. Append-only across protocol versions; existing values are stable.
    ///
    /// @param TRANSFER `transfer`, `transferFrom`, and memo'd variants.
    /// @param MINT     `mint` and `mintWithMemo`.
    /// @param BURN     `burn`, `burnWithMemo`, and the deprecated `burnBlocked`.
    /// @param SEIZE    `seizeWithMemo`.
    enum PausableFeature {
        TRANSFER,
        MINT,
        BURN,
        SEIZE
    }

    /*//////////////////////////////////////////////////////////////
                                ERRORS
    //////////////////////////////////////////////////////////////*/

    /// @notice ETH was attached to a call targeting a nonpayable token selector.
    ///
    /// @dev The precompile checks `msg.value != 0` at the top of dispatch before any other
    ///      validation. All B-20 token selectors are nonpayable.
    error NonPayable();

    /// @notice `account` does not hold `neededRole`.
    ///
    /// @param account    Account that failed the role check.
    /// @param neededRole Role the account was required to hold.
    error AccessControlUnauthorizedAccount(address account, bytes32 neededRole);

    /// @notice Caller failed a positional authorization check that is not expressible as "missing role X".
    error Unauthorized();

    /// @notice The `PausableFeature` covering this operation is currently paused.
    ///
    /// @param feature Paused feature that gated the operation.
    error ContractPaused(PausableFeature feature);

    /// @notice `spender`'s allowance is less than `needed` for the requested `transferFrom`.
    ///
    /// @param spender   Spender whose allowance was insufficient.
    /// @param allowance Current allowance.
    /// @param needed    Allowance required.
    error InsufficientAllowance(address spender, uint256 allowance, uint256 needed);

    /// @notice `sender`'s balance is less than `needed` for the requested transfer or burn.
    ///
    /// @param sender  Account whose balance was insufficient.
    /// @param balance Current balance.
    /// @param needed  Balance required.
    error InsufficientBalance(address sender, uint256 balance, uint256 needed);

    /// @notice The transfer's source address is invalid (typically `address(0)`).
    error InvalidSender(address sender);

    /// @notice The transfer's destination address is invalid (typically `address(0)`).
    error InvalidReceiver(address receiver);

    /// @notice The approval's `owner` address is invalid (typically `address(0)`).
    error InvalidApprover(address approver);

    /// @notice The approval's `spender` address is invalid (typically `address(0)`).
    error InvalidSpender(address spender);

    /// @notice An amount argument was zero where a non-zero value is required. Not used for ERC-20 amount arguments.
    error InvalidAmount();

    /// @notice An empty array was passed to a function that requires at least one element.
    error EmptyFeatureSet();

    /// @notice The proposed supply cap is outside the permitted range: below the current
    ///         `totalSupply`, or above the maximum (`type(uint128).max`).
    ///
    /// @param currentSupply Current `totalSupply`.
    /// @param proposedCap   Rejected proposed cap.
    error InvalidSupplyCap(uint256 currentSupply, uint256 proposedCap);

    /// @notice The mint would push `totalSupply` past the configured cap.
    ///
    /// @param cap       Configured supply cap.
    /// @param attempted Resulting supply that would exceed the cap.
    error SupplyCapExceeded(uint256 cap, uint256 attempted);

    /// @notice A policy slot denied the operation.
    ///
    /// @param policyScope Scope of the slot that denied (e.g. `TRANSFER_SENDER_POLICY`).
    /// @param policyId    Policy ID currently configured in that slot.
    error PolicyForbids(bytes32 policyScope, uint64 policyId);

    /// @notice The provided policy ID does not exist in the policy registry.
    error PolicyNotFound(uint64 policyId);

    /// @notice `policyScope` is not a slot this token (or its variant) supports.
    error UnsupportedPolicyType(bytes32 policyScope);

    /// @notice `seizeWithMemo` was called against a `from` that is currently authorized under
    ///         `SEIZE_HOLDER_POLICY` (i.e. not a member of the seize-holder set).
    error AccountNotSeizable(address account);

    /// @notice The deprecated `burnBlocked` was called against a `from` that is currently authorized under
    ///         `TRANSFER_SENDER_POLICY` (i.e. not blocked).
    error AccountNotBlocked(address account);

    /// @notice An EIP-2612 `permit` was submitted with a `deadline` strictly less than `block.timestamp`.
    error ExpiredSignature(uint256 deadline);

    /// @notice ECDSA recovery on an EIP-2612 `permit` returned `signer`, which does not match the claimed `owner`.
    ///
    /// @param signer Recovered signer.
    /// @param owner  Claimed owner.
    error InvalidSigner(address signer, address owner);

    /// @notice `renounceRole(DEFAULT_ADMIN_ROLE, ...)` was called by the sole remaining admin.
    error LastAdminCannotRenounce();

    /// @notice `renounceLastAdmin()` was called when other accounts also hold `DEFAULT_ADMIN_ROLE`.
    error NotSoleAdmin();

    /// @notice The `callerConfirmation` argument to `renounceRole` was not `msg.sender`.
    error AccessControlBadConfirmation();

    /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice ERC-20 transfer event. Emitted on every successful transfer (including memo'd variants),
    ///         mint (`from = address(0)`), and burn (`to = address(0)`, including `burnBlocked`).
    event Transfer(address indexed from, address indexed to, uint256 amount);

    /// @notice ERC-20 approval event. Emitted by `approve` and `permit`.
    event Approval(address indexed owner, address indexed spender, uint256 amount);

    /// @notice Emitted by `transferWithMemo`, `transferFromWithMemo`, `mintWithMemo`, and `burnWithMemo`
    ///         immediately after the underlying `Transfer` event. `caller` is the `msg.sender` of the memo'd call.
    event Memo(address indexed caller, bytes32 indexed memo);

    /// @notice Emitted by the deprecated `burnBlocked` in addition to `Transfer(from, address(0), amount)`.
    event BurnedBlocked(address indexed caller, address indexed from, uint256 amount);

    /// @notice Emitted by `seizeWithMemo` in addition to `Transfer(from, to, amount)` (and the
    ///         standard `Memo(caller, memo)`). Records a transfer-based seizure: `caller` is the `msg.sender`
    ///         (holder of `SEIZE_ROLE`), `from` the seized account, `to` the destination.
    event Seized(address indexed caller, address indexed from, address indexed to, uint256 amount);

    /// @notice Emitted when `account` is granted `role`. `sender` is the originating caller.
    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);

    /// @notice Emitted when `role` is revoked from `account`. `sender` is the originating caller
    ///         (the admin role bearer via `revokeRole`, or `account` itself via `renounceRole`).
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);

    /// @notice Emitted by `setRoleAdmin` when the admin role for `role` changes.
    event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previousAdminRole, bytes32 indexed newAdminRole);

    /// @notice Emitted by `renounceLastAdmin` in addition to the standard
    ///         `RoleRevoked(DEFAULT_ADMIN_ROLE, previousAdmin, previousAdmin)` event.
    event LastAdminRenounced(address indexed previousAdmin);

    /// @notice Emitted by `pause`. `features` is the argument to the call (not the resulting paused state).
    event Paused(address indexed updater, PausableFeature[] features);

    /// @notice Emitted by `unpause`. `features` is the argument to the call (not the resulting paused state).
    event Unpaused(address indexed updater, PausableFeature[] features);

    /// @notice Emitted by `updatePolicy` when a token's policy slot is changed. Initial slot assignment at
    ///         creation is also emitted via `PolicyUpdated` with `oldPolicyId == 0`.
    event PolicyUpdated(bytes32 indexed policyScope, uint64 oldPolicyId, uint64 newPolicyId);

    /// @notice Emitted by `updateSupplyCap`.
    event SupplyCapUpdated(address indexed updater, uint256 oldSupplyCap, uint256 newSupplyCap);

    /// @notice Emitted by `updateContractURI`. Per ERC-7572, parameterless: integrators re-fetch `contractURI()`.
    event ContractURIUpdated();

    /// @notice Emitted by `updateName`. Carries the new name string.
    event NameUpdated(address indexed updater, string newName);

    /// @notice Emitted by `updateSymbol`. Carries the new symbol string.
    event SymbolUpdated(address indexed updater, string newSymbol);

    /// @notice ERC-5267 domain-change signal. Emitted exactly once per successful `updateName` call,
    ///         immediately after `NameUpdated`. `updateSymbol` does NOT emit this event.
    event EIP712DomainChanged();

    /*//////////////////////////////////////////////////////////////
                              ROLE CONSTANTS
    //////////////////////////////////////////////////////////////*/

    /// @notice The default top-level admin role (`bytes32(0)`). Required to call `grantRole`, `revokeRole`,
    ///         `setRoleAdmin`, `updatePolicy`, and `updateSupplyCap`.
    /// @return Role constant.
    function DEFAULT_ADMIN_ROLE() external view returns (bytes32);

    /// @notice Required to call `mint` and `mintWithMemo`.
    /// @return Role constant.
    function MINT_ROLE() external view returns (bytes32);

    /// @notice Required to call `burn` and `burnWithMemo`.
    /// @return Role constant.
    function BURN_ROLE() external view returns (bytes32);

    /// @notice Required to call the deprecated `burnBlocked`.
    /// @return Role constant.
    function BURN_BLOCKED_ROLE() external view returns (bytes32);

    /// @notice Required to call `seizeWithMemo`.
    /// @return Role constant.
    function SEIZE_ROLE() external view returns (bytes32);

    /// @notice Required to call `pause`.
    /// @return Role constant.
    function PAUSE_ROLE() external view returns (bytes32);

    /// @notice Required to call `unpause`.
    /// @return Role constant.
    function UNPAUSE_ROLE() external view returns (bytes32);

    /// @notice Required to call `updateName`, `updateSymbol`, and `updateContractURI`.
    /// @return Role constant.
    function METADATA_ROLE() external view returns (bytes32);

    /*//////////////////////////////////////////////////////////////
                          POLICY TYPE CONSTANTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Policy slot consulted against `from` on every transfer (including `transferFrom`).
    /// @dev Bypassed for factory-originated calls during the creation (bootstrap) window; see
    ///      `IB20Factory.createB20`.
    /// @return Policy scope constant.
    function TRANSFER_SENDER_POLICY() external view returns (bytes32);

    /// @notice Policy slot consulted against `to` on every transfer.
    /// @dev Bypassed for factory-originated calls during the creation (bootstrap) window; see
    ///      `IB20Factory.createB20`.
    /// @return Policy scope constant.
    function TRANSFER_RECEIVER_POLICY() external view returns (bytes32);

    /// @notice Policy slot consulted against `msg.sender` on `transferFrom` when distinct from `from`.
    ///         Not consulted on `transfer`.
    /// @dev Bypassed for factory-originated calls during the creation (bootstrap) window; see
    ///      `IB20Factory.createB20`.
    /// @return Policy scope constant.
    function TRANSFER_EXECUTOR_POLICY() external view returns (bytes32);

    /// @notice Policy slot consulted against `to` on every mint.
    /// @dev Unlike the transfer-side policies, this slot is ALWAYS enforced — including for
    ///      factory-originated mints during the creation (bootstrap) window — so new supply is never
    ///      issued to a policy-denied recipient even at creation. See `IB20Factory.createB20`.
    /// @return Policy scope constant.
    function MINT_RECEIVER_POLICY() external view returns (bytes32);

    /// @notice Policy slot consulted against `from` by `seizeWithMemo`.
    /// @dev A `from` is seizable only when it is NOT authorized by this policy. An unset slot reads as `0`
    ///      (always-allow), so no account is seizable until an issuer configures the slot.
    /// @return Policy scope constant.
    function SEIZE_HOLDER_POLICY() external view returns (bytes32);

    /// @notice Policy slot consulted against `to` by `seizeWithMemo`.
    /// @dev Mirrors `MINT_RECEIVER_POLICY`: always enforced on the seize destination. An unset slot reads
    ///      as `0` (always-allow), so seize may send anywhere until an issuer configures the slot.
    /// @return Policy scope constant.
    function SEIZE_RECEIVER_POLICY() external view returns (bytes32);

    /*//////////////////////////////////////////////////////////////
                                  ERC-20
    //////////////////////////////////////////////////////////////*/

    /// @notice Token name. Set at creation, mutable via `updateName`.
    /// @return Current token name.
    function name() external view returns (string memory);

    /// @notice Token symbol. Set at creation, mutable via `updateSymbol`.
    /// @return Current token symbol.
    function symbol() external view returns (string memory);

    /// @notice Number of decimal places. Immutable per token variant.
    /// @return Number of decimal places.
    function decimals() external view returns (uint8);

    /// @notice Total token supply currently in circulation.
    /// @return Current total supply.
    function totalSupply() external view returns (uint256);

    /// @notice Balance of `account`.
    ///
    /// @param account Account whose balance is being queried.
    ///
    /// @return Current balance.
    function balanceOf(address account) external view returns (uint256);

    /// @notice Allowance granted by `owner` to `spender`.
    ///
    /// @param owner   Allowance owner.
    /// @param spender Allowance spender.
    ///
    /// @return Current allowance.
    function allowance(address owner, address spender) external view returns (uint256);

    /// @notice Transfers `amount` from `msg.sender` to `to`. Emits `Transfer`.
    ///
    /// @dev Reverts with `ContractPaused(TRANSFER)` when `TRANSFER` is paused.
    /// @dev Reverts with `InvalidReceiver` when `to == address(0)`.
    /// @dev Reverts with `InvalidSender` when `msg.sender == address(0)`.
    /// @dev Reverts with `PolicyForbids(TRANSFER_SENDER_POLICY, ...)` when `msg.sender` is not authorized.
    /// @dev Reverts with `PolicyForbids(TRANSFER_RECEIVER_POLICY, ...)` when `to` is not authorized.
    /// @dev Reverts with `InsufficientBalance` when `msg.sender`'s balance is below `amount`.
    ///
    /// @param to     Destination address.
    /// @param amount Amount to transfer.
    ///
    /// @return Always `true` on success.
    function transfer(address to, uint256 amount) external returns (bool);

    /// @notice Transfers `amount` from `from` to `to` using `msg.sender`'s allowance. Emits `Transfer`.
    ///
    /// @dev Reverts with `ContractPaused(TRANSFER)` when `TRANSFER` is paused.
    /// @dev Reverts with `InvalidReceiver` when `to == address(0)`.
    /// @dev Reverts with `InvalidSender` when `from == address(0)`.
    /// @dev Reverts with `InsufficientAllowance` when the caller's allowance from `from` is below `amount`.
    /// @dev Reverts with `PolicyForbids(TRANSFER_EXECUTOR_POLICY, ...)` when `msg.sender != from` and `msg.sender` is not authorized.
    /// @dev Reverts with `PolicyForbids(TRANSFER_SENDER_POLICY, ...)` when `from` is not authorized.
    /// @dev Reverts with `PolicyForbids(TRANSFER_RECEIVER_POLICY, ...)` when `to` is not authorized.
    /// @dev Reverts with `InsufficientBalance` when `from`'s balance is below `amount`.
    ///
    /// @param from   Source address.
    /// @param to     Destination address.
    /// @param amount Amount to transfer.
    ///
    /// @return Always `true` on success.
    function transferFrom(address from, address to, uint256 amount) external returns (bool);

    /// @notice Sets `spender`'s allowance to `amount`. Not gated by any policy or by pause. Emits `Approval`.
    ///
    /// @dev Reverts with `InvalidApprover` when `msg.sender == address(0)`.
    /// @dev Reverts with `InvalidSpender` when `spender == address(0)`.
    ///
    /// @param spender Account being granted the allowance.
    /// @param amount  Allowance amount.
    ///
    /// @return Always `true` on success.
    function approve(address spender, uint256 amount) external returns (bool);

    /*//////////////////////////////////////////////////////////////
                            METADATA UPDATES
    //////////////////////////////////////////////////////////////*/

    /// @notice Updates the token's `name`. Emits `NameUpdated` followed by `EIP712DomainChanged`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `METADATA_ROLE`.
    ///
    /// @param newName New token name.
    function updateName(string calldata newName) external;

    /// @notice Updates the token's `symbol`. Emits `SymbolUpdated`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `METADATA_ROLE`.
    ///
    /// @param newSymbol New token symbol.
    function updateSymbol(string calldata newSymbol) external;

    /*//////////////////////////////////////////////////////////////
                          MEMO TRANSFER VARIANTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Same as `transfer`, plus emits `Memo` immediately after the standard `Transfer` event.
    ///         A memo of `bytes32(0)` is permitted.
    ///
    /// @param to     Destination address.
    /// @param amount Amount to transfer.
    /// @param memo   Off-chain memo payload.
    ///
    /// @return Always `true` on success.
    function transferWithMemo(address to, uint256 amount, bytes32 memo) external returns (bool);

    /// @notice Same as `transferFrom`, plus emits `Memo` immediately after the standard `Transfer` event.
    ///         A memo of `bytes32(0)` is permitted.
    ///
    /// @param from   Source address.
    /// @param to     Destination address.
    /// @param amount Amount to transfer.
    /// @param memo   Off-chain memo payload.
    ///
    /// @return Always `true` on success.
    function transferFromWithMemo(address from, address to, uint256 amount, bytes32 memo) external returns (bool);

    /*//////////////////////////////////////////////////////////////
                              MINT / BURN
    //////////////////////////////////////////////////////////////*/

    /// @notice Mints `amount` to `to`. Emits `Transfer(address(0), to, amount)`.
    ///
    /// @dev Reverts with `ContractPaused(MINT)` when `MINT` is paused.
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `MINT_ROLE`.
    /// @dev Reverts with `InvalidReceiver` when `to == address(0)`.
    /// @dev Reverts with `PolicyForbids(MINT_RECEIVER_POLICY, ...)` when `to` is not authorized.
    /// @dev Reverts with `SupplyCapExceeded` when `totalSupply + amount > supplyCap`.
    ///
    /// @param to     Mint recipient.
    /// @param amount Amount to mint.
    function mint(address to, uint256 amount) external;

    /// @notice Same as `mint`, plus emits `Memo` immediately after the standard `Transfer` event.
    ///         A memo of `bytes32(0)` is permitted.
    ///
    /// @param to     Mint recipient.
    /// @param amount Amount to mint.
    /// @param memo   Off-chain memo payload.
    function mintWithMemo(address to, uint256 amount, bytes32 memo) external;

    /// @notice Burns `amount` from the caller's own balance. Not subject to any policy.
    ///         Emits `Transfer(caller, address(0), amount)`.
    ///
    /// @dev Reverts with `ContractPaused(BURN)` when `BURN` is paused.
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `BURN_ROLE`.
    /// @dev Reverts with `InsufficientBalance` when the caller's balance is below `amount`.
    ///
    /// @param amount Amount to burn.
    function burn(uint256 amount) external;

    /// @notice Same as `burn`, plus emits `Memo` immediately after the standard `Transfer` event.
    ///         A memo of `bytes32(0)` is permitted.
    ///
    /// @param amount Amount to burn.
    /// @param memo   Off-chain memo payload.
    function burnWithMemo(uint256 amount, bytes32 memo) external;

    /// @notice DEPRECATED. Burns `amount` from a `from` account that is blocked under
    ///         `TRANSFER_SENDER_POLICY`, without spending an allowance. Retained for back-compat;
    ///         prefer `seizeWithMemo` (to a treasury/self address) followed by `burn`.
    ///         Emits `Transfer(from, address(0), amount)` and `BurnedBlocked(caller, from, amount)`.
    ///
    /// @dev Gated by `BURN_BLOCKED_ROLE` and the `BURN` pause vector (not `SEIZE`). Its blocked check
    ///      reads `TRANSFER_SENDER_POLICY`, distinct from `seizeWithMemo`'s `SEIZE_HOLDER_POLICY`.
    /// @dev Reverts with `ContractPaused(BURN)` when `BURN` is paused.
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `BURN_BLOCKED_ROLE`.
    /// @dev Reverts with `AccountNotBlocked` when `from` is currently authorized under `TRANSFER_SENDER_POLICY`.
    /// @dev Reverts with `InsufficientBalance` when `from`'s balance is below `amount`.
    ///
    /// @param from   Account whose blocked balance is being burned.
    /// @param amount Amount to burn.
    function burnBlocked(address from, uint256 amount) external;

    /// @notice Seizes `amount` of `from`'s balance and reassigns it to `to` in a single admin operation.
    ///         Emits, in order, `Transfer(from, to, amount)`, `Memo(caller, memo)`, and
    ///         `Seized(caller, from, to, amount)`. A memo of `bytes32(0)` is permitted.
    ///
    /// @dev Admin operation: skips allowance and the transfer policies. The membership checks are that
    ///      `from` is blocked under `SEIZE_HOLDER_POLICY` and `to` is authorized under `SEIZE_RECEIVER_POLICY`.
    /// @dev `to` is gated by `SEIZE_RECEIVER_POLICY`, which defaults to always-allow when unset, so an
    ///      unconfigured token may seize to any destination (a treasury need not be allowlisted).
    /// @dev Reverts with `ContractPaused(SEIZE)` when `SEIZE` is paused.
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `SEIZE_ROLE`.
    /// @dev Reverts with `InvalidReceiver` when `to == address(0)` or `from == to`.
    /// @dev Reverts with `InvalidSender` when `from == address(0)`.
    /// @dev Reverts with `AccountNotSeizable` when `from` is currently authorized under `SEIZE_HOLDER_POLICY`.
    /// @dev Reverts with `PolicyForbids(SEIZE_RECEIVER_POLICY, ...)` when `to` is not authorized under `SEIZE_RECEIVER_POLICY`.
    /// @dev Reverts with `InsufficientBalance` when `from`'s balance is below `amount`.
    ///
    /// @param from   Account whose balance is being seized.
    /// @param to     Destination address for the seized balance.
    /// @param amount Amount to seize.
    /// @param memo   Memo payload.
    function seizeWithMemo(address from, address to, uint256 amount, bytes32 memo) external;

    /*//////////////////////////////////////////////////////////////
                                  ROLES
    //////////////////////////////////////////////////////////////*/

    /// @notice Whether `account` is a member of `role`. User-defined roles are supported and have no
    ///         built-in effect on the token's own functions.
    ///
    /// @param role    Role to check.
    /// @param account Account to check.
    ///
    /// @return Whether `account` holds `role`.
    function hasRole(bytes32 role, address account) external view returns (bool);

    /// @notice The role required to grant or revoke `role`. Defaults to `DEFAULT_ADMIN_ROLE` if not
    ///         explicitly set via `setRoleAdmin`.
    ///
    /// @param role Role whose admin is being queried.
    ///
    /// @return Admin role.
    function getRoleAdmin(bytes32 role) external view returns (bytes32);

    /// @notice Grants `role` to `account`. Emits `RoleGranted`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold the admin role for `role`,
    ///      or when the token has been transitioned to admin-less via `renounceLastAdmin` (admin-resurrection guard).
    ///
    /// @param role    Role to grant.
    /// @param account Recipient.
    function grantRole(bytes32 role, address account) external;

    /// @notice Revokes `role` from `account`. Emits `RoleRevoked`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold the admin role for `role`,
    ///      or when the token has been transitioned to admin-less via `renounceLastAdmin`.
    /// @dev Reverts with `LastAdminCannotRenounce` when `role == DEFAULT_ADMIN_ROLE` and `account` is the last default admin.
    ///      Use `renounceLastAdmin` to clear the final admin.
    ///
    /// @param role    Role to revoke.
    /// @param account Account to revoke from.
    function revokeRole(bytes32 role, address account) external;

    /// @notice Caller renounces `role` for themselves. Emits `RoleRevoked`.
    ///
    /// @dev Reverts with `AccessControlBadConfirmation` when `callerConfirmation != msg.sender`.
    /// @dev Reverts with `LastAdminCannotRenounce` when `role == DEFAULT_ADMIN_ROLE` and the caller is the last default admin.
    ///
    /// @param role               Role to renounce.
    /// @param callerConfirmation MUST equal `msg.sender`.
    function renounceRole(bytes32 role, address callerConfirmation) external;

    /// @notice Permanently transitions the token to a zero-admin state. Revokes `DEFAULT_ADMIN_ROLE`
    ///         from `msg.sender`. Emits `RoleRevoked(DEFAULT_ADMIN_ROLE, msg.sender, msg.sender)` and
    ///         `LastAdminRenounced(msg.sender)`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when `msg.sender` does not hold `DEFAULT_ADMIN_ROLE`.
    /// @dev Reverts with `NotSoleAdmin` when other accounts also hold `DEFAULT_ADMIN_ROLE`.
    function renounceLastAdmin() external;

    /// @notice Sets the admin role for `role`. Emits `RoleAdminChanged`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold the current admin role for `role`,
    ///      or when the token has been transitioned to admin-less via `renounceLastAdmin`.
    ///
    /// @param role         Role whose admin is being updated.
    /// @param newAdminRole New admin role.
    function setRoleAdmin(bytes32 role, bytes32 newAdminRole) external;

    /*//////////////////////////////////////////////////////////////
                                  PAUSE
    //////////////////////////////////////////////////////////////*/

    /// @notice The `PausableFeature`s currently paused on this token. Order is implementation-defined;
    ///         callers should treat the result as a set.
    /// @return Currently-paused features.
    function pausedFeatures() external view returns (PausableFeature[] memory);

    /// @notice Whether `feature` is currently paused. O(1).
    ///
    /// @param feature Feature to query.
    ///
    /// @return Whether `feature` is paused.
    function isPaused(PausableFeature feature) external view returns (bool);

    /// @notice Pauses each of `features`. Additive: features already paused remain paused; duplicates
    ///         within the call are idempotent. Emits `Paused`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `PAUSE_ROLE`.
    /// @dev Reverts with `EmptyFeatureSet` when `features.length == 0`.
    ///
    /// @param features Features to pause.
    function pause(PausableFeature[] calldata features) external;

    /// @notice Unpauses each of `features`. Features not listed are unaffected; duplicates are idempotent.
    ///         Emits `Unpaused`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `UNPAUSE_ROLE`.
    /// @dev Reverts with `EmptyFeatureSet` when `features.length == 0`.
    ///
    /// @param features Features to unpause.
    function unpause(PausableFeature[] calldata features) external;

    /*//////////////////////////////////////////////////////////////
                                 POLICY
    //////////////////////////////////////////////////////////////*/

    /// @notice The current policy ID configured for `policyScope`. Returns `0` (always-allow built-in)
    ///         for any slot that has never been assigned.
    ///
    /// @dev Reverts with `UnsupportedPolicyType` when `policyScope` is not recognized by this token.
    ///
    /// @param policyScope Policy slot scope.
    ///
    /// @return Configured policy ID.
    function policyId(bytes32 policyScope) external view returns (uint64);

    /// @notice Updates the policy ID assigned to `policyScope`. Takes effect immediately for the next
    ///         operation that consults this slot. Emits `PolicyUpdated`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `DEFAULT_ADMIN_ROLE`.
    /// @dev Reverts with `UnsupportedPolicyType` when `policyScope` is not recognized by this token.
    /// @dev Reverts with `PolicyNotFound` when `newPolicyId` is not a built-in sentinel and does not exist in the registry.
    ///
    /// @param policyScope Policy slot scope.
    /// @param newPolicyId Policy ID to assign to the slot.
    function updatePolicy(bytes32 policyScope, uint64 newPolicyId) external;

    /*//////////////////////////////////////////////////////////////
                              SUPPLY CAP
    //////////////////////////////////////////////////////////////*/

    /// @notice The maximum total supply enforced on `mint`. Capped at `type(uint128).max`, which
    ///         indicates no cap (the unbounded sentinel). `totalSupply` can therefore never exceed
    ///         `type(uint128).max`.
    /// @return Current supply cap.
    function supplyCap() external view returns (uint256);

    /// @notice Sets a new supply cap. May be raised or lowered freely, but never below current
    ///         `totalSupply` and never above `type(uint128).max`. Emits `SupplyCapUpdated`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `DEFAULT_ADMIN_ROLE`.
    /// @dev Reverts with `InvalidSupplyCap` when `newSupplyCap < totalSupply()` or `newSupplyCap > type(uint128).max`.
    ///
    /// @param newSupplyCap New supply cap. Must not exceed `type(uint128).max`.
    function updateSupplyCap(uint256 newSupplyCap) external;

    /*//////////////////////////////////////////////////////////////
                       PERMIT (EIP-2612 + ERC-5267)
    //////////////////////////////////////////////////////////////*/

    /// @notice The current EIP-712 domain separator for this token. Recomputed on each call so it
    ///         remains correct after `updateName` or a chain fork that changes `block.chainid`.
    /// @return Current domain separator.
    function DOMAIN_SEPARATOR() external view returns (bytes32);

    /// @notice The current EIP-2612 permit nonce for `owner`. Incremented by 1 on each successful `permit`.
    ///
    /// @param owner Account whose nonce is being queried.
    ///
    /// @return Current nonce.
    function nonces(address owner) external view returns (uint256);

    /// @notice EIP-2612 permit. Recovers `owner` via ECDSA from `(v, r, s)`. EOA signatures only;
    ///         ERC-1271 contract signatures are NOT supported. Emits `Approval`.
    ///
    /// @dev Reverts with `ExpiredSignature` when `block.timestamp > deadline`.
    /// @dev Reverts with `InvalidSigner` when ECDSA recovery does not yield `owner`.
    /// @dev Reverts with `InvalidSpender` when `spender == address(0)`.
    ///
    /// @param owner    Token holder granting the allowance.
    /// @param spender  Account being granted the allowance.
    /// @param value    Allowance amount.
    /// @param deadline Unix timestamp after which the signature is invalid.
    /// @param v        ECDSA recovery byte.
    /// @param r        ECDSA signature r component.
    /// @param s        ECDSA signature s component.
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s)
        external;

    /// @notice ERC-5267 EIP-712 domain introspection.
    ///
    /// @return fields            Bitmap of populated domain fields (`0x0f`: `name`, `version`, `chainId`, `verifyingContract`).
    /// @return name              Live `name()` value.
    /// @return version           Constant `"1"`.
    /// @return chainId           Current `block.chainid`.
    /// @return verifyingContract This token's address.
    /// @return salt              Unused (zero).
    /// @return extensions        Empty.
    function eip712Domain()
        external
        view
        returns (
            bytes1 fields,
            string memory name,
            string memory version,
            uint256 chainId,
            address verifyingContract,
            bytes32 salt,
            uint256[] memory extensions
        );

    /*//////////////////////////////////////////////////////////////
                          CONTRACT URI (ERC-7572)
    //////////////////////////////////////////////////////////////*/

    /// @notice Off-chain URI pointing at contract-level metadata for this token, per ERC-7572.
    /// @return Current contract URI.
    function contractURI() external view returns (string memory);

    /// @notice Updates `contractURI`. Emits the parameterless `ContractURIUpdated` event per ERC-7572;
    ///         integrators re-fetch `contractURI()` after observing it.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `METADATA_ROLE`.
    ///
    /// @param newURI New contract URI.
    function updateContractURI(string calldata newURI) external;
}

B20/IB20Asset.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.20 <0.9.0;

import {IB20} from "./IB20.sol";
import {IERC165} from "./IERC165.sol";
import {
    IScaledUIAmount,
    IScaledUIAmountNewUIMultiplier,
    IScaledUIAmountBalances,
    IScaledUIAmountConversion
} from "./IERC8056.sol";

/// @title  IB20Asset
/// @author Coinbase
///
/// @notice A B-20 token variant for assets of all kinds. Extends `IB20` with announcements,
///         multiplier-based scaling, batched mint for bulk issuance, and extra-metadata
///         entries.
interface IB20Asset is
    IB20,
    IERC165,
    IScaledUIAmount,
    IScaledUIAmountNewUIMultiplier,
    IScaledUIAmountBalances,
    IScaledUIAmountConversion
{
    /*//////////////////////////////////////////////////////////////
                                 ERRORS
    //////////////////////////////////////////////////////////////*/

    /// @notice `announce` was called with an `id` that has already been consumed.
    error AnnouncementIdAlreadyUsed(string id);

    /// @notice `updateExtraMetadata` was called with an empty `key`.
    error InvalidMetadataKey();

    /// @notice A multiplier setter (`updateUIMultiplier`, or the deprecated `updateMultiplier`) was
    ///         called with a multiplier of zero or above the `type(uint128).max` overflow guard.
    error InvalidMultiplier();

    /// @notice `updateUIMultiplier` was called with an `effectiveAt` that is not in the future
    ///         (`effectiveAt <= block.timestamp`).
    ///
    /// @param effectiveAt Rejected effective-at timestamp.
    error EffectiveAtInPast(uint256 effectiveAt);

    /// @notice `updateUIMultiplier` was called with an `effectiveAt` above `type(uint64).max`, the
    ///         width of the on-chain `effectiveAt` field.
    ///
    /// @param effectiveAt Rejected effective-at timestamp.
    error EffectiveAtTooFar(uint256 effectiveAt);

    /// @notice `updateUIMultiplier` was called while a live pending update already exists
    ///
    /// @param effectiveAt The `effectiveAt` of the live pending update.
    error UIMultiplierUpdateExists(uint256 effectiveAt);

    /// @notice `cancelUIMultiplierUpdate` was called when there is no live pending update
    error UIMultiplierUpdateDoesNotExist();

    /// @notice A batched function was called with parallel arrays of differing lengths.
    ///
    /// @param leftLen  Length of the first array argument.
    /// @param rightLen Length of the second array argument.
    error LengthMismatch(uint256 leftLen, uint256 rightLen);

    /// @notice A batched function was called with empty arrays.
    error EmptyBatch();

    /// @notice An inner call dispatched by `announce` tried to re-invoke `announce`.
    error AnnouncementInProgress();

    /// @notice An inner call dispatched by `announce` was shorter than four bytes.
    ///
    /// @param call Offending raw calldata blob.
    error InternalCallMalformed(bytes call);

    /// @notice An inner call dispatched by `announce` reverted with an ordinary revert; its reason is
    ///         not bubbled. A Solidity `Panic` propagates raw instead (see `announce`).
    ///
    /// @param call Offending raw calldata blob.
    error InternalCallFailed(bytes call);

    /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Deprecated multiplier-change event. The instant setter (`updateUIMultiplier` /
    ///         `updateMultiplier`) emits this alongside `UIMultiplierUpdated` so indexers on the
    ///         legacy topic keep working; the scheduled `updateUIMultiplier` emits only
    ///         `UIMultiplierUpdated`.
    ///
    /// @param multiplier The new immediate multiplier.
    event MultiplierUpdated(uint256 multiplier);

    /// @notice A scheduled multiplier update was cancelled. Emitted by `cancelUIMultiplierUpdate`,
    ///         and by `updateUIMultiplier` when it clears a live pending update.
    ///
    /// @param cancelledMultiplier  The pending multiplier that was cleared.
    /// @param cancelledEffectiveAt The `effectiveAt` of the pending update that was cleared.
    event UIMultiplierUpdateCancelled(uint256 cancelledMultiplier, uint256 cancelledEffectiveAt);

    /// @notice Emitted by `updateExtraMetadata`. An empty `value` indicates removal.
    event ExtraMetadataUpdated(string key, string value);

    /// @notice Emitted by `announce` to open an announcement bracket.
    event Announcement(address indexed caller, string id, string description, string uri);

    /// @notice Emitted by `announce` to close the bracket opened by the paired `Announcement` with the same `id`.
    event EndAnnouncement(string id);

    /*//////////////////////////////////////////////////////////////
                              ROLE CONSTANTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Required to call `announce`, `updateUIMultiplier`, `cancelUIMultiplierUpdate`, and
    ///         `updateUIMultiplier`. The metadata setters (`updateName`, `updateSymbol`,
    ///         `updateExtraMetadata`) are gated by the inherited `METADATA_ROLE` instead.
    /// @return Role constant.
    function OPERATOR_ROLE() external view returns (bytes32);

    /*//////////////////////////////////////////////////////////////
                              PRECISION
    //////////////////////////////////////////////////////////////*/

    /// @notice Fixed-point precision used to scale `multiplier`. Equal to `1e18`.
    /// @return Precision constant.
    function WAD_PRECISION() external view returns (uint256);

    /// @notice The maximum multiplier the setters accept: `type(uint128).max`, the overflow guard.
    ///         Exposed so callers can read the bound without triggering the `InvalidMultiplier`
    ///         revert path. With supply capped at `type(uint128).max`, a `uint128` multiplier keeps
    ///         `balance * multiplier` inside `uint256`.
    /// @return Maximum UI multiplier constant.
    function MAX_UI_MULTIPLIER() external view returns (uint256);

    /*//////////////////////////////////////////////////////////////
                              ANNOUNCEMENTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Posts a holder-impacting announcement and atomically dispatches each entry in
    ///         `internalCalls` via self-`delegatecall` (preserving `msg.sender`). Emits
    ///         `Announcement` then `EndAnnouncement` with the same `id`. Pass an empty
    ///         `internalCalls` for a pure disclosure.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `OPERATOR_ROLE`.
    /// @dev Reverts with `AnnouncementIdAlreadyUsed` when `id` has previously been consumed.
    /// @dev Reverts with `InternalCallMalformed` when an entry in `internalCalls` is shorter than four bytes.
    /// @dev Reverts with `AnnouncementInProgress` when an entry in `internalCalls` targets `announce` itself.
    /// @dev An inner call that raises a Solidity `Panic` (e.g. arithmetic overflow) propagates the
    ///      raw Panic unchanged; any other inner revert wraps as `InternalCallFailed(call)`. An inner
    ///      out-of-gas halts the whole call.
    ///
    /// @param internalCalls ABI-encoded calldata blobs executed in order via self-`delegatecall`; may be empty.
    /// @param id            Caller-chosen announcement id; single-use over the token's lifetime.
    /// @param description   Human-readable summary of the announcement.
    /// @param uri           Off-chain URI containing the full announcement contents.
    function announce(
        bytes[] calldata internalCalls,
        string calldata id,
        string calldata description,
        string calldata uri
    ) external;

    /// @notice Whether `id` has previously been consumed by `announce`.
    ///
    /// @param id Announcement id to query.
    ///
    /// @return Whether `id` is used.
    function isAnnouncementIdUsed(string calldata id) external view returns (bool);

    /*//////////////////////////////////////////////////////////////
                               MULTIPLIER
    //////////////////////////////////////////////////////////////*/

    /// @notice The current multiplier, scaled to `WAD_PRECISION`. Holder balances are stored
    ///         as raw units; the multiplier scales them into a derived "scaled" view, similar
    ///         in shape to wstETH wrapping stETH.
    ///
    /// @dev Alias of the ERC-8056 `uiMultiplier()`.
    ///
    /// @return Current (effective) multiplier.
    function multiplier() external view returns (uint256);

    /// @notice DEPRECATED. Converts a raw balance to its scaled view:
    ///         `rawBalance * multiplier / WAD_PRECISION`. Retained (dialable) for backward
    ///         compatibility; prefer the ERC-8056 Conversion extension `toUIAmount`.
    ///
    /// @param rawBalance Raw token amount to scale.
    ///
    /// @return Scaled balance at the current multiplier.
    function toScaledBalance(uint256 rawBalance) external view returns (uint256);

    /// @notice DEPRECATED. Converts a scaled balance back to its raw representation:
    ///         `scaledBalance * WAD_PRECISION / multiplier`. Retained (dialable) for backward
    ///         compatibility; prefer the ERC-8056 Conversion extension `fromUIAmount`.
    ///
    /// @dev Integer division rounds toward zero; conversions are not exactly reversible when
    ///      `multiplier != WAD_PRECISION`. `toRawBalance(toScaledBalance(x))` may return a
    ///      value slightly less than `x`.
    ///
    /// @param scaledBalance Scaled token amount to convert back.
    ///
    /// @return rawBalance Raw balance at the current multiplier.
    function toRawBalance(uint256 scaledBalance) external view returns (uint256 rawBalance);

    /// @notice Convenience for `toUIAmount(balanceOf(account))`.
    ///
    /// @param account Account whose scaled balance is being queried.
    ///
    /// @return Scaled balance.
    function scaledBalanceOf(address account) external view returns (uint256);

    /// @notice Schedules a UI-multiplier update to take effect at `effectiveAt` — the canonical path
    ///         for corporate actions (splits, reinvested dividends).
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `OPERATOR_ROLE`.
    /// @dev Reverts with `InvalidMultiplier` when `newMultiplier` is zero or above `type(uint128).max`.
    /// @dev Reverts with `EffectiveAtInPast` when `effectiveAt` is not in the future.
    /// @dev Reverts with `EffectiveAtTooFar` when `effectiveAt` exceeds `type(uint64).max`.
    /// @dev Reverts with `UIMultiplierUpdateExists` when a live pending update already exists.
    ///
    /// @param newMultiplier New multiplier scaled to `WAD_PRECISION`.
    /// @param effectiveAt   Timestamp at which `newMultiplier` becomes effective; must be in the future.
    function updateUIMultiplier(uint256 newMultiplier, uint256 effectiveAt) external;

    /// @notice Cancels the single live pending update, restoring the no-pending state
    ///         (`effectiveAt` resets to 0).
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `OPERATOR_ROLE`.
    /// @dev Reverts with `UIMultiplierUpdateDoesNotExist` when there is no live pending update.
    function cancelUIMultiplierUpdate() external;

    /// @notice DEPRECATED. Instant failsafe / emergency override — sets the current multiplier
    ///         immediately and cancels any live pending update without a scheduling window, emitting
    ///         both `MultiplierUpdated` and `UIMultiplierUpdated`. Retained (dialable) for backward
    ///         compatibility; prefer the scheduled `updateUIMultiplier` for routine corporate actions.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `OPERATOR_ROLE`.
    /// @dev Reverts with `InvalidMultiplier` when `newMultiplier` is zero or above `type(uint128).max`.
    ///
    /// @param newMultiplier New multiplier scaled to `WAD_PRECISION`; must be in `(0, type(uint128).max]`.
    function updateMultiplier(uint256 newMultiplier) external;

    /*//////////////////////////////////////////////////////////////
                            BATCHED ISSUANCE
    //////////////////////////////////////////////////////////////*/

    /// @notice Mints `amounts[i]` to `recipients[i]` in one call. All-or-nothing: any element
    ///         revert unwinds the whole transaction. Emits `Transfer(address(0), recipients[i], amounts[i])`
    ///         per element.
    ///
    /// @dev Reverts with `ContractPaused(MINT)` when `MINT` is paused.
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `MINT_ROLE`.
    /// @dev Reverts with `LengthMismatch` when `recipients.length != amounts.length`.
    /// @dev Reverts with `EmptyBatch` when either array is empty.
    /// @dev Reverts with `InvalidReceiver` when any `recipients[i] == address(0)`.
    /// @dev Reverts with `PolicyForbids(MINT_RECEIVER_POLICY, ...)` when any recipient is not authorized.
    /// @dev Reverts with `SupplyCapExceeded` when the cumulative mint would exceed the cap.
    ///
    /// @param recipients Accounts receiving the minted tokens.
    /// @param amounts    Per-recipient amounts, parallel to `recipients`.
    function batchMint(address[] calldata recipients, uint256[] calldata amounts) external;

    /*//////////////////////////////////////////////////////////////
                             EXTRA METADATA
    //////////////////////////////////////////////////////////////*/

    /// @notice The value of the named metadata entry, or the empty string if not set. A
    ///         variant-agnostic key/value store; the issuer chooses the key namespace
    ///         (e.g. `"category"`, `"region"`, `"reference"`).
    ///
    /// @param key Metadata entry key.
    ///
    /// @return Current value, or the empty string.
    function extraMetadata(string calldata key) external view returns (string memory);

    /// @notice Sets, updates, or removes an extra-metadata entry. An empty `value` removes the
    ///         entry. Emits `ExtraMetadataUpdated`.
    ///
    /// @dev Reverts with `AccessControlUnauthorizedAccount` when the caller does not hold `METADATA_ROLE`.
    /// @dev Reverts with `InvalidMetadataKey` when `key` is the empty string.
    ///
    /// @param key   Metadata entry key (e.g. `"category"`).
    /// @param value New value, or empty string to remove.
    function updateExtraMetadata(string calldata key, string calldata value) external;
}

